(function(E){ const x = E["sales-m4"] = E["sales-m4"] || {units:{}}; x.units["sales-4-3"] = {"grammar":{"id":"c-sales-4-3-g","level":"B1","course":"sales","unit":"sales-4-3","title":"Talking about results: fell from 9 to 2, dropped by 35%","titleTr":"Sonuçları anlatmak: fell from 9 to 2, dropped by 35%","titleFa":"حرف زدن درباره‌ی نتیجه‌ها: fell from 9 to 2، dropped by 35%","formsTable":{"headers":{"en":["Question","Word","Example"],"tr":["Soru","Kelime","Örnek"],"fa":["سؤال","کلمه","مثال"]},"rows":[["How much did it change?","by","Returns have dropped by 35%."],["From what to what?","from ... to","Stockouts have fallen from 9 to 2 a year."],["Up to now?","present perfect + since","... have fallen since June."],["A finished period?","past simple","In June we delivered 6,000 kilos."]]},"wrong":"Returns have dropped with 35% since June.","right":"Returns have dropped by 35% since June.","blank":{"sentence":"Stockouts in your shops have fallen ___ 9 to 2 a year.","word":"from","distractors":["of","since"]},"wrong2":"Stockouts fell from 9 at 2 a year.","right2":"Stockouts fell from 9 to 2 a year.","blank2":{"sentence":"Late deliveries fell from 6 ___ 1 this year.","word":"to","distractors":["at","by"]},"expParts":{"tryFrom":"blank","rule":[{"en":"by = the size of the change.","tr":"by = değişimin büyüklüğü.","fa":"کلمه‌ی by اندازه‌ی تغییر را می‌گوید.","ex":"Returns have dropped by 35%."},{"en":"from ... to = the start and the end.","tr":"from ... to = başlangıç ve bitiş.","fa":"عبارت from ... to عدد شروع و عدد پایان را می‌گوید.","ex":"fell from 9 to 2 a year"},{"en":"Up to now: present perfect. A finished period: past simple.","tr":"Şu ana kadar: present perfect. Bitmiş bir dönem: past simple.","fa":"برای تغییری که تا حالا ادامه دارد حال کامل می‌آوری و برای دوره‌ی تمام‌شده گذشته‌ی ساده.","ex":"have fallen since June / In June we delivered..."}],"test":{"en":"Ask 'How much?': use by. Ask 'From what to what?': use from ... to.","tr":"'Ne kadar?' diye sor: by. 'Kaçtan kaça?' diye sor: from ... to.","fa":"اگر می‌پرسی «چقدر؟»، by بیاور. اگر می‌پرسی «از چند به چند؟»، from ... to بیاور."},"contrast":{"en":"Turkish says '%35 düştü' with no preposition and '40'tan 6'ya' with endings, and Persian «۳۵ درصد کاهش یافت». So learners drop by, or use 'with'. English needs by for the size and from ... to for the numbers.","tr":"Türkçede '%35 düştü' deriz, edat kullanmayız; '40'tan 6'ya' derken de ekler kullanırız. Bu yüzden İngilizcede by atlanıyor ya da 'with' kullanılıyor. İngilizcede büyüklük için by, sayılar için from ... to gerekir.","fa":"در فارسی می‌گوییم «۳۵ درصد کاهش یافت» و «از ۴۰ به ۶». برای همین خیلی از ما by را جا می‌اندازیم یا with می‌گذاریم. در انگلیسی برای اندازه‌ی تغییر by و برای عددها from ... to لازم است."}},"errorWatch":[{"find":["dropped with","fallen with","fell with","increased with","rose with","risen with","grown with","decreased with"],"fix":{"en":"Use by for the size of a change: 'dropped by 35%'.","tr":"Değişimin büyüklüğü için by kullan: 'dropped by 35%'.","fa":"برای اندازه‌ی تغییر by به کار ببر: «dropped by 35%»."}},{"find":["from 9 at","increased of","decreased of","dropped of","rose of","fell of"],"fix":{"en":"from ... to for the numbers; by for the change: 'fell from 9 to 2', 'rose by 8%'.","tr":"Rakamlar için from ... to, değişim için by: 'fell from 9 to 2', 'rose by 8%'.","fa":"برای عددها from ... to می‌آید و برای اندازه‌ی تغییر by: «fell from 9 to 2»، «rose by 8%»."}}]},"b2":{"id":"c-sales-4-3-b2","level":"B2","track":"B2","course":"sales","unit":"sales-4-3","title":"Trends in a report: a sharp fall in / fell sharply","titleTr":"Raporda eğilimler: a sharp fall in / fell sharply","titleFa":"روندها در گزارش: a sharp fall in و fell sharply","formsTable":{"headers":{"en":["Verb + adverb","Adjective + noun"],"tr":["Fiil + zarf","Sıfat + isim"],"fa":["فعل و قید","صفت و اسم"]},"rows":[["Returns fell sharply.","a sharp fall in returns"],["Freight costs rose slightly.","a slight rise in freight costs"],["Repeat orders grew steadily.","a steady increase in repeat orders"]]},"wrong":"There has been a sharp fall of returns.","right":"There has been a sharp fall in returns.","blank":{"sentence":"There has been a slight ___ in freight costs.","word":"rise","distractors":["rising","risen"]},"wrong2":"Returns fell sharp after the first delivery.","right2":"Returns fell sharply after the first delivery.","blank2":{"sentence":"Late deliveries dropped ___ in the first month.","word":"sharply","distractors":["sharp","sharpness"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"Verb + adverb: fell sharply, rose slightly.","tr":"Fiil + zarf: fell sharply, rose slightly.","fa":"فعل را با قید می‌آوری: fell sharply و rose slightly.","ex":"Returns fell sharply."},{"en":"Adjective + noun: a sharp fall, a slight rise.","tr":"Sıfat + isim: a sharp fall, a slight rise.","fa":"یا صفت را با اسم می‌آوری: a sharp fall و a slight rise.","ex":"There has been a sharp fall in returns."},{"en":"a rise in + the thing; a rise of + the number.","tr":"a rise in + değişen şey; a rise of + sayı.","fa":"بعد از a rise in چیزی می‌آید که تغییر کرده و بعد از a rise of عدد.","ex":"a rise of 8% in freight costs"}],"test":{"en":"Is the word next to a verb? Add -ly. Next to a noun? No -ly.","tr":"Kelime bir fiilin yanında mı? -ly ekle. Bir ismin yanında mı? -ly yok.","fa":"کلمه کنار فعل است؟ ‎-ly اضافه کن. کنار اسم است؟ ‎-ly لازم نیست."},"contrast":{"en":"Turkish uses one word for both ('keskin bir düşüş', 'keskin biçimde düştü' only adds 'biçimde'), and Persian says «کاهش شدید» and «به‌شدت کاهش یافت». English changes the word: sharp, sharply; and chooses in or of after the noun.","tr":"Türkçede 'keskin bir düşüş' ve 'keskin biçimde düştü' deriz; kelimenin kendisi değişmez. İngilizcede kelime değişir: sharp (isimle), sharply (fiille). İsimden sonra da in ya da of seçilir.","fa":"در فارسی می‌گوییم «کاهش شدید» و «به‌شدت کاهش یافت». در انگلیسی خود کلمه عوض می‌شود: sharp کنار اسم و sharply کنار فعل؛ و بعد از اسم باید بین in و of انتخاب کرد."}},"errorWatch":[{"find":["fell sharp","rose sharp","dropped sharp","grew steady","rose slight","fell slight","increased steady"],"fix":{"en":"With a verb, use the adverb: 'fell sharply', 'rose slightly'.","tr":"Fiille birlikte zarf kullan: 'fell sharply', 'rose slightly'.","fa":"با فعل، قید به کار ببر: «fell sharply»، «rose slightly»."}},{"find":["fall of returns","rise of freight","increase of repeat","drop of costs","fall of costs"],"fix":{"en":"a fall in + the thing: 'a sharp fall in returns'.","tr":"a fall in + o şey: 'a sharp fall in returns'.","fa":"بعد از a fall in چیزی می‌آید که تغییر کرده است: «a sharp fall in returns»."}}],"useIn":{"en":"B2: describe one trend with an adjective + noun (a sharp fall in...) and one with a verb + adverb.","tr":"B2: bir eğilimi sıfat + isimle (a sharp fall in...), birini de fiil + zarfla anlat.","fa":"مسیر B2: یک روند را با صفت و اسم (a sharp fall in...) و یکی را با فعل و قید توصیف کن."},"exitItem":{"from":"sales-4-3","kind":"blank","prompt":"We saw a steady ___ in reorders.","options":["increase","increasing","increased"],"correct":0}},"vocab":{"id":"c-sales-4-3-v","level":"B1","category":"vocab","course":"sales","unit":"sales-4-3","goals":["career"],"title":{"en":"Reviewing an account","tr":"Müşteriyi gözden geçirmek","fa":"مرور وضعیت مشتری"},"cards":[{"word":"account review","sentence":"We hold an account review every six months.","meaning":{"en":"A meeting to look at how the business with one customer is going.","tr":"müşteri değerlendirme toplantısı.","fa":"جلسه‌ی مرور حساب مشتری"}},{"word":"result","sentence":"The result surprised both of us.","meaning":{"en":"What happens because of something.","tr":"sonuç.","fa":"نتیجه"}},{"word":"trend","sentence":"The trend is clear: orders rise in autumn.","meaning":{"en":"The general way something is changing.","tr":"eğilim.","fa":"روند"}},{"word":"drop","sentence":"Returns have dropped this year.","gap":"dropped","accept":["dropped","drop"],"meaning":{"en":"To go down.","tr":"düşmek, azalmak.","fa":"کاهش یافتن"}},{"word":"rise","sentence":"Freight costs have risen since March.","gap":"risen","accept":["risen","rise"],"meaning":{"en":"To go up.","tr":"artmak, yükselmek.","fa":"افزایش یافتن"}},{"word":"stockout","sentence":"A stockout means lost sales for the shop.","meaning":{"en":"When a shop has none of a product left.","tr":"stok tükenmesi","fa":"تمام شدن موجودی"}},{"word":"upsell","sentence":"Don't upsell before you have solved the problem.","meaning":{"en":"Selling an existing customer something more.","tr":"mevcut müşteriye ek ürün satışı.","fa":"فروش بیشتر به مشتری فعلی"}},{"word":"repeat order","sentence":"A repeat order is the best proof of a good deal.","meaning":{"en":"A second order of the same thing.","tr":"tekrar sipariş.","fa":"سفارش تکراری"}},{"word":"feedback","sentence":"Could we have your feedback on the last delivery?","meaning":{"en":"Comments about how well something works.","tr":"geri bildirim.","fa":"بازخورد"}},{"word":"next step","sentence":"The next step is a trial in two more shops.","meaning":{"en":"What you will do after this.","tr":"sonraki adım.","fa":"قدم بعدی"}}]},"judge":{"id":"c-sales-4-3-j","course":"sales","unit":"sales-4-3","type":"judge","title":{"en":"A review or a sales pitch?","tr":"Değerlendirme mi, satış sunumu mu?","fa":"مرور یا فروش پنهان؟"},"prompt":"Four openings for a review with a chain of food shops.","parts":["Their goal","Numbers","Honest"],"instruction":{"en":"Tap what each opening has. The best one has all three.","tr":"Her açılışta ne olduğuna dokun. En iyisinde üçü de var.","fa":"روی چیزهایی که هر شروع دارد بزن. بهترین شروع هر سه را دارد."},"items":[{"by":"New rep","answer":"We have worked very hard for you this year. We sent 60 emails. Now let me show you our new products.","present":[],"fix":{"en":"It's about you, and it jumps to selling. Start with their goal and one result.","tr":"Seninle ilgili ve hemen satışa atlıyor. Onların hedefi ve bir sonuçla başla.","fa":"درباره‌ی خودت است و یک‌دفعه سراغ فروش می‌رود. با هدف آن‌ها و یک نتیجه شروع کن."}},{"by":"AI tool","answer":"It has been a truly fantastic year of partnership, with amazing growth across all areas and metrics.","present":[],"fix":{"en":"No goal, no real number, and nothing true enough to trust. Give the figures, including a bad one.","tr":"Hedef yok, gerçek rakam yok, güvenilecek doğru bir şey de yok. İyi ve kötü rakamları ver.","fa":"نه هدفی، نه عدد واقعی و نه چیزی که بشود به آن اعتماد کرد. عددها را، از جمله یک عدد بد، بگو."}},{"by":"Sales rep","answer":"Your goal was no empty shelves. Stockouts have fallen from 9 to 2 a year, so all is perfect.","present":["Their goal","Numbers"],"fix":{"en":"A strong start, but it hides the late order. Say it yourself before they do.","tr":"Güçlü bir başlangıç ama geciken siparişi saklıyor. Onlar söylemeden kendin söyle.","fa":"شروع قوی است، ولی سفارشی را که دیر رسیده پنهان می‌کند. قبل از اینکه آن‌ها بگویند، خودت بگو."}},{"by":"Good model","answer":"Your goal was no empty shelves. Stockouts have fallen from 9 to 2 a year. One order came 8 days late, and we have changed the ship on your route.","present":["Their goal","Numbers","Honest"],"fix":null}]},"speaking":{"id":"sales-4-3","course":"sales","unit":"sales-4-3","topic":{"en":"Presenting results to a customer","tr":"Sonuçları müşteriye sunmak","fa":"ارائه‌ی نتیجه‌ها به مشتری"},"warmup":{"en":"Think of your best customer. What was their goal this year?","tr":"En iyi müşterini düşün. Bu yılki hedefi neydi?","fa":"بهترین مشتری‌ات را در نظر بگیر. هدفش امسال چه بود؟"},"questions":[{"en":"Open the review with the customer's goal and two good results. Use from ... to and by. Yours, or: goal, no empty shelves; stockouts from 9 to 2 a year; returns down by 35%; one order 8 days late, so you changed the ship.","tr":"Değerlendirmeyi müşterinin hedefi ve iki iyi sonuçla aç. From ... to ve by kullan. Kendi müşterin ya da şu: hedef, boş raf olmaması; stok tükenmesi yılda 9'dan 2'ye; iadeler %35 azaldı; bir sipariş 8 gün geç kaldı, bu yüzden gemiyi değiştirdin.","fa":"مرور را با هدف مشتری و دو نتیجه‌ی خوب شروع کن. از from ... to و by استفاده کن. از مشتری خودت بگو یا از این نمونه استفاده کن. هدف: نداشتن قفسه‌ی خالی؛ کمبود موجودی از ۹ به ۲ بار در سال؛ مرجوعی‌ها ۳۵ درصد کمتر؛ یک سفارش ۸ روز دیر رسید و کشتی را عوض کردی."},{"en":"Now give the bad number yourself, and say what you changed.","tr":"Şimdi kötü rakamı kendin söyle ve ne değiştirdiğini anlat.","fa":"حالا عدد بد را خودت بگو و توضیح بده چه چیزی را تغییر دادی."},{"en":"Ask what has changed in their business, and suggest one next step that fits.","tr":"İşlerinde neyin değiştiğini sor ve uygun bir sonraki adım öner.","fa":"بپرس در کارشان چه چیزی عوض شده و یک قدم بعدی مناسب پیشنهاد کن."}],"followups":[{"en":"Which number would you show your own best customer? What would you want to hear from them?","tr":"Kendi en iyi müşterine hangi rakamı gösterirdin? Ondan ne duymak isterdin?","fa":"به بهترین مشتری خودت کدام عدد را نشان می‌دهی؟ دوست داری از او چه بشنوی؟"}],"expressions":[{"phrase":"Your goal was ...","meaning":{"en":"Starts from their goal.","tr":"Onların hedefinden başlar.","fa":"از هدف آن‌ها شروع می‌کند."}},{"phrase":"... has fallen from ... to ...","meaning":{"en":"Shows a change in numbers.","tr":"Rakamlarla bir değişimi gösterir.","fa":"تغییر را با عدد نشان می‌دهد."}},{"phrase":"What has changed on your side?","meaning":{"en":"Opens the talk.","tr":"Konuşmayı açar.","fa":"گفت‌وگو را باز می‌کند."}}],"model":"Your goal this year was no empty shelves. Stockouts have fallen from nine to two a year, and returns have dropped by thirty-five percent. One order came eight days late, so we have changed the ship on your route. What has changed on your side? You're opening two shops? Then shall we plan the first delivery for them together, in March?","selfCheck":[{"en":"I started with their goal.","tr":"Onların hedefiyle başladım.","fa":"با هدف آن‌ها شروع کردم."},{"en":"I said the bad number myself.","tr":"Kötü rakamı kendim söyledim.","fa":"عدد بد را خودم گفتم."},{"en":"I used by and from ... to correctly.","tr":"By ve from ... to'yu doğru kullandım.","fa":"by و from ... to را درست به کار بردم."},{"en":"My next step fits their need.","tr":"Sonraki adımım onların ihtiyacına uyuyor.","fa":"قدم بعدی‌ام با نیازشان جور است."}]},"writing":{"id":"c-sales-4-3-w","course":"sales","unit":"sales-4-3","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your account plan","tr":"Müşteri planın","fa":"برنامه‌ی حساب مشتری تو"},"portfolio":"sales-final-7","prompt":{"en":"Use a real customer, or: a chain of food shops; goal: no empty shelves; stockouts down from 9 to 2 a year; returns down 35%; one order 8 days late; two new shops in spring. Write the review email (80-110 words): their goal, two good results, the bad number and what changed, one question about their plans, and next steps with dates.","tr":"Gerçek bir müşteri ya da şunu kullan: bir gıda mağazası zinciri; hedef: boş raf olmaması; stok tükenmesi yılda 9'dan 2'ye düştü; iadeler %35 azaldı; bir sipariş 8 gün gecikti; ilkbaharda iki yeni mağaza. Değerlendirme e-postasını yaz (80-110 kelime): hedefleri, iki iyi sonuç, kötü rakam ve ne değiştiği, planlarıyla ilgili bir soru, tarihli sonraki adımlar.","fa":"از یک مشتری واقعی یا این استفاده کن: یک فروشگاه زنجیره‌ای مواد غذایی؛ هدف: قفسه‌ی خالی نباشد؛ کمبود موجودی از ۹ به ۲ بار در سال رسیده؛ مرجوعی ۳۵ درصد کم شده؛ یک سفارش ۸ روز دیر رسیده؛ دو فروشگاه تازه در بهار. ایمیل مرور را بنویس (۸۰ تا ۱۱۰ کلمه): هدفشان، دو نتیجه‌ی خوب، عدد بد و چیزی که تغییر کرد، یک سؤال درباره‌ی برنامه‌هایشان و قدم‌های بعدی با تاریخ."},"model":"Dear Ms Lindgren,\n\nThank you for your time today. Your goal was no empty shelves. Stockouts have fallen from 9 to 2 a year, and returns have dropped by 35%. One order came 8 days late, so we have changed the ship on your route.\n\nYou told me that two new shops open in spring. How many cartons will each shop need?\n\nNext steps: you will send opening dates by 10 January. We will send a delivery plan by 20 January. We will review the numbers again in June.\n\nBest regards","frame":"Dear ___,\n\nThank you for ___. Your goal was ___. ___ have fallen from ___ to ___, and ___ have dropped by ___. One ___, so we have ___.\n\nYou told me that ___. How ___?\n\nNext steps: you will ___ by ___. We will ___ by ___.\n\nBest regards","words":[{"word":"from 9 to 2"},{"word":"dropped by"},{"word":"Next steps"}],"minWords":70,"minSentences":5,"rubric":["Task done: goal, two results, the bad number, one question, dated next steps","Organised: their goal first, the next steps last","Language: by, from ... to; present perfect up to now","Tone: honest about the bad number; no hidden selling"],"rubricI18n":{"tr":["Görev: hedef, iki sonuç, kötü rakam, bir soru, tarihli sonraki adımlar","Düzen: önce onların hedefi, en sonda sonraki adımlar","Dil: by, from ... to; şimdiye kadarki için present perfect","Üslup: kötü rakam konusunda dürüst; gizli satış yok"],"fa":["کامل بودن کار: هدف، دو نتیجه، عدد بد، یک سؤال، قدم‌های بعدی با تاریخ","نظم: اول هدف آن‌ها، آخر قدم‌های بعدی","زبان: by و from ... to؛ حال کامل برای کارهای تا الان","لحن: صادق درباره‌ی عدد بد؛ بدون فروش پنهان"]}},"exit":{"id":"c-sales-4-3-x","course":"sales","unit":"sales-4-3","type":"exit","items":[{"from":"sales-4-3","kind":"blank","prompt":"Freight costs have risen ___ 8% since March.","options":["by","with","of"],"correct":0,"point":2},{"from":"sales-4-3","kind":"mcq","prompt":"What should an account review start with?","options":["Your new products","The customer's goal","How many emails you sent"],"correct":1,"point":1},{"from":"sales-4-3","kind":"mcq","prompt":"When should you offer the customer something more?","options":["In the first minute, before anything else","Only when it fits a need they told you about","In every email, so they never forget it"],"correct":1,"point":1},{"from":"sales-4-2","kind":"blank","prompt":"I'm afraid the certificate ___ yet.","options":["hasn't come","isn't come","didn't came"],"correct":0},{"from":"sales-3-2","kind":"mcq","prompt":"The buyer asks for 60 days to pay. Which reply is a trade?","options":["Sure, no problem. Take 60 days, or more if you like.","If you signed for a year, we could give you 60 days.","That's impossible. We never do that for any customer."],"correct":1},{"from":"sales-2-2","kind":"mcq","prompt":"How should an Incoterm be written?","options":["The rule alone, such as FOB","The rule, the place and the year","The rule and the price per kilo"],"correct":1}]},"explain":{"id":"c-sales-4-3-e","course":"sales","unit":"sales-4-3","type":"explain","level":"B1","title":{"en":"Account review and the next order","tr":"Müşteri değerlendirmesi ve sonraki sipariş","fa":"مرور حساب مشتری و سفارش بعدی"},"objective":{"en":"In this lesson you will learn to review an account with numbers, against the customer's goals, and agree the next step.","tr":"Bu derste bir müşteriyi rakamlarla, onun hedeflerine göre gözden geçirmeyi ve bir sonraki adımda anlaşmayı öğreneceksin.","fa":"در این درس یاد می‌گیری وضعیت یک مشتری را با عدد و در مقایسه با هدف‌های خودش مرور کنی و روی قدم بعدی توافق کنی."},"hook":{"en":"An account review shows results against the customer's goal, not a list of your activity. Keeping a good customer usually costs less than finding a new one, so don't wait until they complain.","tr":"Müşteri değerlendirmesi, yaptıklarının listesini değil, müşterinin hedefine göre sonuçları gösterir. İyi bir müşteriyi tutmak genellikle yenisini bulmaktan daha ucuzdur; o yüzden şikâyet etmesini bekleme.","fa":"مرور حساب مشتری نتیجه‌ها را در مقایسه با هدف مشتری نشان می‌دهد، نه فهرست کارهای تو را. نگه داشتن مشتری خوب معمولاً کم‌هزینه‌تر از پیدا کردن مشتری تازه است؛ پس منتظر شکایتش نمان."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Run the review in four parts","tr":"Değerlendirmeyi dört bölümde yap","fa":"مرور را در چهار بخش پیش ببر"},"steps":[{"en":"Start with their goal, not your activity, because their goal is what they paid for.","tr":"Kendi yaptıklarınla değil, onların hedefiyle başla; çünkü para ödedikleri şey o hedeftir.","fa":"با هدف آن‌ها شروع کن، نه با کارهای خودت؛ چون آن‌ها برای همین هدف پول داده‌اند.","ex":"Your goal was no empty shelves in winter."},{"en":"Show the numbers: two good results and the bad one. Honesty makes the good numbers believable.","tr":"Rakamları göster: iki iyi sonuç ve kötü olan. Dürüstlük, iyi rakamları inandırıcı yapar.","fa":"عددها را نشان بده: دو نتیجه‌ی خوب و یکی بد. صداقت، عددهای خوب را باورپذیر می‌کند.","ex":"Stockouts fell from 9 to 2. One order came late."},{"en":"Ask what has changed in their business, so your next plan fits their plans.","tr":"İşlerinde neyin değiştiğini sor; sonraki planın onların planlarına uysun.","fa":"بپرس در کارشان چه چیزی عوض شده تا برنامه‌ی بعدی‌ات با برنامه‌های آن‌ها جور شود.","ex":"What has changed in your plans for next year?"},{"en":"Agree next steps. Offer more only if it fits their need, or you lose trust.","tr":"Sonraki adımlarda anlaş. Yalnızca ihtiyaçlarına uyuyorsa daha fazlasını öner; yoksa güven kaybedersin.","fa":"روی قدم‌های بعدی توافق کن. فقط اگر با نیازشان جور است چیز بیشتری پیشنهاد بده، وگرنه اعتماد از بین می‌رود.","ex":"You're opening two shops. Shall we plan for them?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Talking about results: fell from 9 to 2, dropped by 35%","tr":"Sonuçları anlatmak: fell from 9 to 2, dropped by 35%","fa":"حرف زدن درباره‌ی نتیجه‌ها: fell from 9 to 2، dropped by 35%"},"steps":[{"en":"by = the size of the change.","tr":"by = değişimin büyüklüğü.","fa":"کلمه‌ی by اندازه‌ی تغییر را می‌گوید.","ex":"Returns have dropped by 35%."},{"en":"from ... to = the start and the end.","tr":"from ... to = başlangıç ve bitiş.","fa":"عبارت from ... to عدد شروع و عدد پایان را می‌گوید.","ex":"fell from 9 to 2 a year"},{"en":"Up to now: present perfect. A finished period: past simple.","tr":"Şu ana kadar: present perfect. Bitmiş bir dönem: past simple.","fa":"برای تغییری که تا حالا ادامه دارد حال کامل می‌آوری و برای دوره‌ی تمام‌شده گذشته‌ی ساده.","ex":"have fallen since June / In June we delivered..."}],"table":{"headers":{"en":["Question","Word","Example"],"tr":["Soru","Kelime","Örnek"],"fa":["سؤال","کلمه","مثال"]},"rows":[["How much did it change?","by","Returns have dropped by 35%."],["From what to what?","from ... to","Stockouts have fallen from 9 to 2 a year."],["Up to now?","present perfect + since","... have fallen since June."],["A finished period?","past simple","In June we delivered 6,000 kilos."]]},"tip":{"en":"Turkish says '%35 düştü' with no preposition and '40'tan 6'ya' with endings, and Persian «۳۵ درصد کاهش یافت». So learners drop by, or use 'with'. English needs by for the size and from ... to for the numbers.","tr":"Türkçede '%35 düştü' deriz, edat kullanmayız; '40'tan 6'ya' derken de ekler kullanırız. Bu yüzden İngilizcede by atlanıyor ya da 'with' kullanılıyor. İngilizcede büyüklük için by, sayılar için from ... to gerekir.","fa":"در فارسی می‌گوییم «۳۵ درصد کاهش یافت» و «از ۴۰ به ۶». برای همین خیلی از ما by را جا می‌اندازیم یا with می‌گذاریم. در انگلیسی برای اندازه‌ی تغییر by و برای عددها from ... to لازم است."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Listen more than you present","tr":"Sunmaktan çok dinle","fa":"بیشتر گوش بده، کمتر ارائه کن"},"body":{"en":"Prepare with your contact, not alone, and ask what they want to discuss. Leave half the time for talk. Write the agreed actions, who does them and by when, and send them that day.","tr":"Yalnız değil, müşterinle birlikte hazırlan ve neyi konuşmak istediklerini sor. Sürenin yarısını sohbete bırak. Anlaşılan işleri, kimin yapacağını ve ne zamana kadar yapacağını yazıp aynı gün gönder.","fa":"تنها آماده نشو؛ با مخاطبت در آن شرکت هماهنگ کن و بپرس می‌خواهد درباره‌ی چه چیزی حرف بزند. نصف زمان را برای گفت‌وگو بگذار. کارهای توافق‌شده، مسئول هر کار و مهلتش را بنویس و همان روز بفرست."},"phrases":[{"phrase":"Your goal was ...","meaning":{"en":"Starts from their goal.","tr":"Onların hedefinden başlar.","fa":"از هدف آن‌ها شروع می‌کند."}},{"phrase":"... has fallen from ... to ...","meaning":{"en":"Shows a change in numbers.","tr":"Rakamlarla bir değişimi gösterir.","fa":"تغییر را با عدد نشان می‌دهد."}},{"phrase":"What has changed on your side?","meaning":{"en":"Opens the talk.","tr":"Konuşmayı açar.","fa":"گفت‌وگو را باز می‌کند."}},{"phrase":"repeat order","meaning":{"en":"A second order of the same thing.","tr":"tekrar sipariş.","fa":"سفارش تکراری"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From activity to result","tr":"Yapılanlardan sonuçlara","fa":"از کارها به نتیجه"},"item":"This year we sent you 14 shipments and 60 emails, and we held many meetings. Your facts: their goal: no empty shelves; stockouts (times the product ran out) down from 9 to 2 a year; one order 8 days late; you changed the ship.","answer":"Your goal was no empty shelves. Stockouts have fallen from 9 to 2 a year. One order came 8 days late, and we have changed the ship for your route.","walk":[{"en":"Nobody cares how many emails you sent. Start from their goal.","tr":"Kaç e-posta gönderdiğin kimsenin umurunda değil. Onların hedefinden başla.","fa":"اینکه چند ایمیل فرستادی برای کسی مهم نیست. از هدف آن‌ها شروع کن."},{"en":"Use from ... to, so the change is easy to see.","tr":"From ... to kullan ki değişim kolay görülsün.","fa":"عبارت from ... to را به کار ببر تا تغییر راحت دیده شود."},{"en":"Say the bad number yourself, with what you changed.","tr":"Kötü rakamı kendin söyle, ne değiştirdiğinle birlikte.","fa":"عدد بد را خودت بگو، همراه با چیزی که تغییر دادی."}]},"quick":{"prompt":"An account review should measure results against ___.","options":["the customer's goals","your sales targets","how many calls you made"],"correct":0,"why":{"en":"the customer's goals: that shows the value they got. Your activity doesn't.","tr":"the customer's goals: aldıkları değeri bu gösterir. Senin yaptıkların göstermez.","fa":"جواب the customer's goals است، چون این نشان می‌دهد چه ارزشی گرفته‌اند؛ کارهای تو این را نشان نمی‌دهد."}},"remember":{"en":"Their goal, your numbers, their news, the next step. You can now lead a review with honest numbers and agree what happens next.","tr":"Onların hedefi, senin rakamların, onların haberleri, sonraki adım. Artık dürüst rakamlarla bir değerlendirme yürütebilir ve sonraki adımda anlaşabilirsin.","fa":"از هدف آن‌ها شروع کن، عددهایت را بگو، خبرهای آن‌ها را بپرس و روی قدم بعدی توافق کن. حالا می‌توانی مرور را با عددهای صادقانه پیش ببری."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Trends in a report: a sharp fall in / fell sharply","tr":"Raporda eğilimler: a sharp fall in / fell sharply","fa":"روندها در گزارش: a sharp fall in و fell sharply"},"steps":[{"en":"Verb + adverb: fell sharply, rose slightly.","tr":"Fiil + zarf: fell sharply, rose slightly.","fa":"فعل را با قید می‌آوری: fell sharply و rose slightly.","ex":"Returns fell sharply."},{"en":"Adjective + noun: a sharp fall, a slight rise.","tr":"Sıfat + isim: a sharp fall, a slight rise.","fa":"یا صفت را با اسم می‌آوری: a sharp fall و a slight rise.","ex":"There has been a sharp fall in returns."},{"en":"a rise in + the thing; a rise of + the number.","tr":"a rise in + değişen şey; a rise of + sayı.","fa":"بعد از a rise in چیزی می‌آید که تغییر کرده و بعد از a rise of عدد.","ex":"a rise of 8% in freight costs"}],"table":{"headers":{"en":["Verb + adverb","Adjective + noun"],"tr":["Fiil + zarf","Sıfat + isim"],"fa":["فعل و قید","صفت و اسم"]},"rows":[["Returns fell sharply.","a sharp fall in returns"],["Freight costs rose slightly.","a slight rise in freight costs"],["Repeat orders grew steadily.","a steady increase in repeat orders"]]},"body":{"en":"B2: describe one trend with an adjective + noun (a sharp fall in...) and one with a verb + adverb.","tr":"B2: bir eğilimi sıfat + isimle (a sharp fall in...), birini de fiil + zarfla anlat.","fa":"مسیر B2: یک روند را با صفت و اسم (a sharp fall in...) و یکی را با فعل و قید توصیف کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
